def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    result = []
    for cls in classes:
        if not any(cls is other or issubclass(cls, other) for other in result):
            result.append(cls)
    return result

