    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    if extract_spec_version:
        type_value = inventory.get('type')
        if type_value is not None:
            # Attempt to extract spec version from the type value
            # Assuming type_value is a string that might contain version info
            # For example, "inventory/v1" or similar
            if isinstance(type_value, str):
                # Simple heuristic: look for a version pattern like /v\d+
                import re
                match = re.search(r'/v(\d+)', type_value)
                if match:
                    self.spec_version = int(match.group(1))
                else:
                    # If no version found in type, keep existing self.spec_version
                    pass
            else:
                # If type is not a string, we can't extract version, keep existing
                pass
        # If type_value is None, keep existing self.spec_version

    # Now perform validation based on self.spec_version
    # This is a placeholder for actual validation logic
    # In a real implementation, you would have different validation rules
    # for different spec versions.

    # For the purpose of this example, we'll just check that the inventory
    # has the required fields for the current spec version.

    # Example: For spec version 1, we might require 'name' and 'items'
    if self.spec_version == 1:
        required_fields = ['name', 'items']
        for field in required_fields:
            if field not in inventory:
                raise ValueError(f"Missing required field '{field}' for spec version {self.spec_version}")

        # Validate that 'items' is a list
        if not isinstance(inventory.get('items'), list):
            raise ValueError("'items' must be a list for spec version 1")

    elif self.spec_version == 2:
        required_fields = ['name', 'items', 'metadata']
        for field in required_fields:
            if field not in inventory:
                raise ValueError(f"Missing required field '{field}' for spec version {self.spec_version}")

        # Validate that 'items' is a list
        if not isinstance(inventory.get('items'), list):
            raise ValueError("'items' must be a list for spec version 2")

        # Validate that 'metadata' is a dict
