def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("Inventory cannot be None")
    if version is None:
        raise ValueError("Version cannot be None")

    # Assuming inventory is a dictionary mapping versions to their state
    # and each state contains logical paths and their corresponding content files.
    # The structure is assumed to be:
    # inventory = {
    #     version: {
    #         logical_path: set_of_content_files,
    #         ...
    #     },
    #     ...
    # }

    if version not in inventory:
        raise KeyError(f"Version {version} not found in inventory")

    state = inventory[version]

    # Ensure the state is a dictionary
    if not isinstance(state, dict):
        raise TypeError("State for the given version must be a dictionary")

    # Build the map of logical paths to sets of content files
    logical_path_map = {}
    for logical_path, content_files in state.items():
        # Ensure content_files is a set; if not, convert it
        if not isinstance(content_files, set):
            content_files = set(content_files)
        logical_path_map[logical_path] = content_files

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("Fixity 'files' must be a list")

    for file_entry in files:
        if not isinstance(file_entry, dict):
            raise ValueError("Each file entry in fixity must be a dictionary")

        if 'path' not in file_entry:
            raise ValueError("Each file entry in fixity must contain a 'path' key")

        file_path = file_entry['path']
        if file_path not in manifest_files:
            raise ValueError("File '%s' in fixity block is not listed in the manifest" % file_path)

