    """Call the given command(s)."""
    import subprocess
    import os

    # Combine commands and args into a single list
    full_command = list(commands) + list(args)

    # Prepare environment
    if env is None:
        env = os.environ.copy()
    else:
        env = os.environ.copy()
        env.update(env)

    # Prepare subprocess kwargs
    kwargs = {
        'cwd': cwd,
        'env': env,
        'stdout': subprocess.PIPE,
        'stderr': subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
    }

    if verbose:
        print("Running command: {}".format(' '.join(full_command)))

    try:
        process = subprocess.Popen(full_command, **kwargs)
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)
        return stdout
    except Exception as e:
        if verbose:
