def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    def _merge_mapping_nodes(mapping1, mapping2):
        """
        Deep merge two MappingNodes.
        """
        merged = []
        # Create a map of key value to index in mapping1
        key_to_index = {}
        for i, (key, value) in enumerate(mapping1.value):
            key_to_index[key.value] = i

        for key, value in mapping2.value:
            if key.value in key_to_index:
                idx = key_to_index[key.value]
                existing_key, existing_value = mapping1.value[idx]
                # If both are MappingNodes, deep merge
                if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                    merged_value = _merge_mapping_nodes(existing_value, value)
                    mapping1.value[idx] = (existing_key, merged_value)
                else:
                    # Last value wins
                    mapping1.value[idx] = (key, value)
            else:
                # Add new key-value pair
                mapping1.value.append((key, value))
                key_to_index[key.value] = len(mapping1.value) - 1

        return mapping1

    # Group nodes by their key value
    key_to_nodes = {}
    for key, value in nodes:
        if key.value not in key_to_nodes:
            key_to_nodes[key.value] = []
        key_to_nodes[key.value].append((key, value))

    result = []
    for key_value, node_list in key_to_nodes.items():
        if len(node_list) == 1:
            result.append(node_list[0])
        else:
            # Merge all nodes with the same key
            # Start with the first one
            merged_key, merged_value = node_list[0]
            for i in range(1, len(node_list)):
                next_key, next_value = node_list[i]
                if isinstance(merged_value, MappingNode) and isinstance(next_value, MappingNode):
                    merged_value = _merge_mapping_nodes(merged_value, next_value)
                else:
                    # Last value wins
                    merged_value = next_value
            result.append((merged_key, merged_value))

    return result
