def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0
    if platform not in (0, 1):
        raise ValueError("platform must be 'this', 0, or 1")
    if platform == 1:
        # POSIX: split on whitespace, respect quotes
        # Use a regex that matches quoted strings or unquoted tokens
        pattern = r'(?:"([^"]*)"|\'([^\']*)\'|(\S+))'
        tokens = []
        for match in re.finditer(pattern, s):
            if match.group(1) is not None:
                tokens.append(match.group(1))
            elif match.group(2) is not None:
                tokens.append(match.group(2))
            else:
                tokens.append(match.group(3))
        return tokens
    else:
        # Windows/CMD: split on whitespace, respect quotes (simplified)
        # Windows command line parsing is complex, but for basic use,
        # we can use a similar approach to POSIX but with different quote handling
        # For simplicity, we'll use a basic regex that handles double quotes
        pattern = r'(?:"([^"]*)"|(\S+))'
        tokens = []
        for match in re.finditer(pattern, s):
            if match.group(1) is not None:
                tokens.append(match.group(1))
            else:
                tokens.append(match.group(2))
        return tokens

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if filename is None:
        filename = os.path.basename(archive_path)
    tmp_dir = os.path.join(str(tmp_path), "repo_archive")
    os.makedirs(tmp_dir, exist_ok=True)
    extract_path = os.path.join(tmp_dir, filename)
    if os.path.exists(extract_path):
        shutil.rmtree(extract_path)
    if archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
        subprocess.run(["tar", "-xzf", archive_path, "-C", tmp_dir], check=True)
    elif archive_path.endswith(".tar.bz2") or archive_path.endswith(".tbz2"):
        subprocess.run(["tar", "-xjf", archive_path, "-C", tmp_dir], check=True)
    elif archive_path.endswith(".zip"):
        subprocess.run(["unzip", "-q", archive_path, "-d", tmp_dir], check=True)
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")
    # Find the extracted directory (assuming single top-level directory)
    entries = os.listdir(tmp_dir)
    if len(entries) == 1:
        repo_path = os.path.join(tmp_dir, entries[0])
    else:
        repo_path = tmp_dir
    return f"file://{repo_path}"

