        print("Running command: {}".format(" ".join(full_cmd)))
    try:
        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = None
        subprocess.check_call(full_cmd, cwd=cwd, env=env, stderr=stderr)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Command '{}' failed with exit code {}".format(" ".join(full_cmd), e.returncode))

