def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda x: x
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")
    if scale is True:
        scale = hist.scale
    points = []
    for bin_ in hist.bins:
        if get_coordinate == "left":
            x = bin_.left
        elif get_coordinate == "right":
            x = bin_.right
        else:
            x = (bin_.left + bin_.right) / 2.0
        y = make_value(bin_.content)
        points.append((x, y))
    graph = Graph(field_names=field_names, scale=scale)
    for point in points:
        graph.add_point(point)
    return graph

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")
    if not issubclass(candidate, iface):
        if tentative:
            return False
        raise TypeError("candidate %s is not a subclass of iface %s" % (candidate, iface))
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = [type(base) for base in bases]
    if not metaclasses:
        return type
    # Find the most derived metaclass
    for mc in metaclasses:
        for other in metaclasses:
            if other is not mc and issubclass(mc, other):
                break
        else:
            return mc
    # If there is a conflict, raise a TypeError
    raise TypeError("metaclass conflict")

