def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if "links" in data:
            return data
        else:
            raise ValueError("Invalid JSON webfinger document")
    except json.JSONDecodeError:
        pass

    try:
        root = ElementTree.fromstring(document)
        links = []
        for link in root.findall(".//{urn:xmpp:webfinger:1.0}link"):
            link_dict = {
                "rel": link.get("rel"),
                "type": link.get("type"),
                "template": link.get("template"),
                "href": link.get("href"),
            }
            links.append(link_dict)
        return {"links": links}
    except ElementTree.ParseError:
        raise ValueError("Invalid webfinger document")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        return None

    url = "https://{}/.well-known/webfinger?resource=acct:{}".format(host, quote(handle))
    try:
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            return response.text
    except requests.RequestException:
        pass
    return None

