    # This is a simplified example; in a real scenario, this would be
    # derived from the parser's definition or a configuration.
    type_map = {
        'port': int,
        'timeout': float,
        'verbose': bool,
        'count': int,
        'size': int,
        'rate': float,
        'enabled': bool,
        'debug': bool,
        'retries': int,
        'delay': float
    }

    for key, value in values_dict.items():
        if value is None:
            continue

        # If the key is in our type map, attempt to convert the value
        if key in type_map:
            target_type = type_map[key]
            try:
                if target_type is bool:
                    # Handle boolean conversion specially since bool("false") is True
                    if isinstance(value, str):
                        value_lower = value.lower()
                        if value_lower in ('true', '1', 'yes', 'on'):
                            values_dict[key] = True
                        elif value_lower in ('false', '0', 'no', 'off'):
                            values_dict[key] = False
                        else:
                            # If it's not a clear boolean string, leave it or raise
                            # For robustness, we might just leave it as is or try bool()
                            values_dict[key] = bool(value)
                    else:
                        values_dict[key] = bool(value)
                else:
                    values_dict[key] = target_type(value)
            except (ValueError, TypeError):
                # If conversion fails, leave the original value or handle error
                # For this implementation, we leave the original value to avoid crashing
                pass
        else:
            # If the key is not in the type map, we might try to infer type
            # or just leave it as a string. For now, we leave it as is.
            pass

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found: {spec_file}")

    try:
        with open(spec_file, 'r') as f:
            spec = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in plugin spec file: {e}")

    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = self.config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with root: {} does not start with {}".format(path, root))
    return path[len(root):]
